def commit_v7(s3, bucket, payload):
    key = "metadata/v7.json"
    try:
        s3.put_object(
            Bucket=bucket, Key=key,
            Body=payload, IfNoneMatch="*",
        )
    except ClientError as err:
        meta = err.response["ResponseMetadata"]
        if meta["HTTPStatusCode"] in (409, 412):
            s3.put_object(
                Bucket=bucket, Key=key, Body=payload
            )
            return
        raise
